Here is a Python function that finds the longest common subsequence of two input strings using dynamic programming:

```python
def longest_common_subsequence(text1: str, text2: str) -> str:
    m, n = len(text1), len(text2)
    # Create a 2D array to store the lengths of longest common subsequences
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Build the dp table in bottom-up manner
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if text1[i - 1] == text2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Reconstruct the longest common subsequence from the dp table
    lcs = []
    i, j = m, n
    while i > 0 and j > 0:
        if text1[i - 1] == text2[j - 1]:
            lcs.append(text1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] >= dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    # Since we reconstructed the sequence backwards, reverse it before returning
    return "".join(reversed(lcs))
```

